INSERT INTO inventories (
    id, ticket_id, total_stock, available_stock, reserved_stock, created_at, updated_at
) VALUES (
    #{id}, #{ticketId}, #{totalStock}, #{availableStock}, #{reservedStock},
    #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE inventories
SET total_stock = total_stock - #{quantity},
    available_stock = available_stock - #{quantity},
    updated_at = NOW()
WHERE ticket_id = #{ticketId}
  AND available_stock >= #{quantity}

UPDATE inventories
SET available_stock = available_stock - #{quantity},
    reserved_stock = reserved_stock + #{quantity},
    updated_at = NOW()
WHERE ticket_id = #{ticketId}
  AND available_stock >= #{quantity}

UPDATE inventories
SET available_stock = available_stock + #{quantity},
    reserved_stock = reserved_stock - #{quantity},
    updated_at = NOW()
WHERE ticket_id = #{ticketId}
  AND reserved_stock >= #{quantity}
